      if (!$storex.ui.isMobile && $storex.ui.viewMode === 'vibe') {
        return
      }

      // Unified opener: a dockview panel on desktop, its own route on mobile.
      // `openChat` → `openApp('chat', …)` decides which, so the store no longer
