      const board = $storex.projects.allBoards.find(({ title }) => title === boardTitle)
      let column = board?.columns?.find(({ title }) => title === columnTitle)
      if (!column) {
        const boardState = $storex.projects.kanban.boards[boardTitle] || { columns: [] }
